-- 1. 增加备注字段（幂等）
SET @exist = (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='t_api_permission' AND column_name='remark');
SET @sql = IF(@exist=0, 'ALTER TABLE t_api_permission ADD COLUMN remark VARCHAR(255) DEFAULT NULL COMMENT ''接口备注''', 'SELECT 1');
PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;

-- 2. 写入所有接口（存在则更新权限码和备注）



-- WI-023 商业化挂账 / 应收账款
ON DUPLICATE KEY UPDATE permission_code=VALUES(permission_code), remark=VALUES(remark);
